  /**
   * The console session of this request.
   *
   * For a request made with the session cookie: who it acts as, when it ends, and its CSRF token. A request made with the cookie that changes anything must send that token as `x-memhouse-csrf`, and every request made with the cookie must come from the server's own origin; otherwise it is refused with 403 and audited (`access.denied`, rule `csrf`). Answers 404 to a request made with a key or token.
   *
   * `GET /v1/session`. Stability: stable.
   *
   * - `options.user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
   */
  session(options: { user?: string } = {}): Promise<SessionInfo> {
    return this.call("GET", "/v1/session", { headers: { "x-memhouse-user": options.user } });
  }

  /**
   * Log in to the console.
   *
   * Opens a console session for the key presented with this request (`Authorization: Bearer <key>`; an agent token opens none). The answer sets the session cookie: `HttpOnly`, `SameSite=Strict`, and `Secure` under the name `__Host-memhouse_session` unless the request came for a loopback host (`[server] session_cookie_secure`). The session has the key's permissions, lasts `[server] session_ttl_secs` at most and ends when unused for `session_idle_secs`, on logout, and when the key is revoked or its principal disabled. The session secret is not in the body. Audited as `session.login`.
   *
   * `POST /v1/session`. Stability: stable.
   *
   * - `options.user`: The user the call acts for. Accepted only from admins and from agents trusted to act for users (`act_as`); a user's key always acts for that user, a token for its own user.
   * - `options.actor`: (deprecated) Ignored since 1.1: the audit actor and `provenance.agent` are the authenticated principal.
   */
